1	/**
2	 * Spectrum/iMessage transport for the relationship agent.
3	 *
4	 * Transports adapt external channels into `InboundAgentMessage` and must stay thin: normalize
5	 * inbound text, call the agent, send replies, and log compact traces. Product decisions stay in
6	 * the agent core and deterministic tools.
7	 */
8	import { Spectrum } from "spectrum-ts";
9	import { imessage } from "spectrum-ts/providers/imessage";
10	import { createInterpretedRelationshipAgent, type AgentExpressionComposer } from "../interpretedAgent";
11	import { polishOutboundText } from "../expressionComposer";
12	import { readExpressionConfig } from "../expressionConfig";
13	import {
14	  createOpenAIInterpreter,
15	  type MessageInterpreter,
16	  readOpenAIConfig
17	} from "../openAIInterpreter";
18	import { loadFriendyEnv, readSpectrumCredentials } from "../env";
19	import { fixtureLongEvent, fixtureShortEvent, fixtureUser } from "../fixtures";
20	import { resolveConfiguredUserId } from "../identity";
21	import type { OnboardingStateController } from "../onboardingState";
22	import type { RelationshipRepository } from "../repository";
23	import { createRuntimeRelationshipRepository } from "../runtimeRepository";
24	import { readFriendyStrictMode } from "../strictMode";
25	import { createRelationshipTools } from "../tools";
26	import type { AgentInteraction, InboundAgentMessage } from "../types";
27	
28	type RelationshipTools = ReturnType<typeof createRelationshipTools>;
29	
30	/** Minimal Spectrum event shape before conversion to `InboundAgentMessage`. */
31	export type SpectrumInboundInput = {
32	  interactionId?: string;
33	  userId?: string;
34	  text: string;
35	  spaceId?: string;
36	  receivedAt: string;
37	};
38	
39	/** Dependencies injectable for tests and fixture runs of the Spectrum runtime. */
40	export type SpectrumRuntimeOptions = {
41	  interpreter: MessageInterpreter;
42	  now?: () => string;
43	  repo?: RelationshipRepository;
44	  tools?: RelationshipTools;
45	  expression?: AgentExpressionComposer;
46	  onboarding?: OnboardingStateController;
47	  requeueDeferredContactsOnStart?: () => Promise<void>;
48	  env?: Partial<NodeJS.ProcessEnv>;
49	};
50	
51	/** Options for starting the live Spectrum message loop. */
52	export type StartSpectrumFriendyAgentOptions = {
53	  interpreter?: MessageInterpreter;
54	  now?: () => string;
55	  repo?: RelationshipRepository;
56	  tools?: RelationshipTools;
57	  expression?: AgentExpressionComposer;
58	  onboarding?: OnboardingStateController;
59	  requeueDeferredContactsOnStart?: () => Promise<void>;
60	  env?: Partial<NodeJS.ProcessEnv>;
61	};
62	
63	/** Compact backend trace emitted after each handled inbound message. */
64	export type CompactInteractionLog = {
65	  interactionId: string;
66	  userId: string;
67	  platform: string;
68	  intent: string;
69	  toolCalls: string[];
70	  trace?: {
71	    traceId: string;
72	    toolCallCount: number;
73	    candidateCount: number;
74	    memoryCount: number;
75	    hasError: boolean;
76	    strictMode?: boolean;
77	    routeSource?: string;
78	    fallbackUsed?: boolean;
79	    scopeDecision?: string;
80	    activeWorkflowKind?: string;
81	    selectedTool?: string;
82	    modelRequested?: string;
83	    modelResponseSchemaValid?: boolean;
84	    modelErrorCode?: string;
85	    searchOutcome?: string;
86	  };
87	  modelUsed?: string;
88	  confidence?: number;
89	  latencyMs?: number;
90	  error?: "present";
91	  createdAt: string;
92	};
93	
94	/** Optional verbose local-server turn log with raw inbound text and sent reply. */
95	export type AgentTurnLog = {
96	  userId: string;
97	  platform: string;
98	  spaceId?: string;
99	  userText: string;
100	  agentReply: string;
101	  createdAt: string;
102	};
103	
104	type SpectrumFriendyRuntime = Pick<ReturnType<typeof createSpectrumFriendyRuntime>, "handleInboundText">;
105	
106	type SpectrumInboundResponderOptions = {
107	  runtime: SpectrumFriendyRuntime;
108	  input: SpectrumInboundInput;
109	  reply(text: string): Promise<void> | void;
110	  logger?: Pick<Console, "info" | "error">;
111	};
112	
113	type SpectrumInboundResponderResult = {
114	  handled: boolean;
115	};
116	
117	const INBOUND_RECOVERY_REPLY = "I had trouble understanding that. Try saying it another way.";
118	
119	/** Converts a Spectrum/iMessage event into the normalized message consumed by the relationship agent. */
120	export function toInboundAgentMessage(input: SpectrumInboundInput, env: Partial<NodeJS.ProcessEnv> = {}): InboundAgentMessage {
121	  return {
122	    interactionId: input.interactionId,
123	    userId: resolveSpectrumUserId(input, env),
124	    platform: "imessage",
125	    spaceId: input.spaceId,
126	    text: input.text,
127	    receivedAt: input.receivedAt
128	  };
129	}
130	
131	/**
132	 * Creates the testable Spectrum runtime.
133	 *
134	 * Spectrum remains only the communication source. This runtime normalizes text, delegates all
135	 * relationship behavior to the interpreted agent, and returns the compact log the live loop prints.
136	 */
137	export function createSpectrumFriendyRuntime({
138	  interpreter,
139	  now,
140	  repo: providedRepo,
141	  tools: providedTools,
142	  expression: providedExpression,
143	  onboarding,
144	  requeueDeferredContactsOnStart,
145	  env = process.env
146	}: SpectrumRuntimeOptions) {
147	  const repo = providedRepo ?? createRuntimeRelationshipRepository({
148	    env,
149	    seed: {
150	      users: [fixtureUser],
151	      calendarEvents: [fixtureLongEvent, fixtureShortEvent]
152	    }
153	  });
154	  const tools = providedTools ?? createRelationshipTools(repo);
155	  const strictMode = readFriendyStrictMode(env);
156	  const expression = providedExpression ?? createEnvExpressionComposer(env);
157	  const agent = createInterpretedRelationshipAgent({
158	    repo,
159	    tools,
160	    expression,
161	    onboarding,
162	    requeueDeferredContactsOnStart,
163	    interpreter,
164	    strictMode,
165	    now
166	  });
167	
168	  return {
169	    repo,
170	    async handleInboundText(input: SpectrumInboundInput) {
171	      const inbound = toInboundAgentMessage(input, env);
172	      const result = await agent.handleMessage(inbound);
173	
174	      return {
175	        replyText: result.outbound.text,
176	        log: toCompactInteractionLog(result.interaction),
177	        turnLog: toAgentTurnLog(inbound, result.outbound.text, result.interaction.createdAt)
178	      };
179	    }
180	  };
181	}
182	
183	/** Handles one Spectrum inbound message without letting a failed turn stop the live loop. */
184	export async function respondToSpectrumInbound({
185	  runtime,
186	  input,
187	  reply,
188	  logger = console
189	}: SpectrumInboundResponderOptions): Promise<SpectrumInboundResponderResult> {
190	  try {
191	    const result = await runtime.handleInboundText(input);
192	    logger.info("[friendy:agent_turn]", JSON.stringify(result.turnLog));
193	    logger.info("[friendy:agent_interaction]", JSON.stringify(result.log));
194	    await reply(result.replyText);
195	    return { handled: true };
196	  } catch (error) {
197	    const message = error instanceof Error ? error.message : String(error);
198	    logger.error(`[friendy:inbound_agent:error] ${message}`);
199	    await reply(INBOUND_RECOVERY_REPLY);
200	    return { handled: false };
201	  }
202	}
203	
204	/**
205	 * Starts the Spectrum-backed relationship agent.
206	 *
207	 * This is a transport scaffold for the fixture number. User identity and durable memory are still
208	 * fixture-scoped here; the agent core is already separated so those pieces can be swapped later.
209	 */
210	export async function startSpectrumFriendyAgent({
211	  interpreter,
212	  now,
213	  repo,
214	  tools,
215	  expression,
216	  onboarding,
217	  requeueDeferredContactsOnStart,
218	  env = process.env
219	}: StartSpectrumFriendyAgentOptions = {}) {
220	  loadFriendyEnv();
221	  const { projectId, projectSecret } = readSpectrumCredentials(env as NodeJS.ProcessEnv);
222	  const modelConfig = readOpenAIConfig(env);
223	  const strictMode = readFriendyStrictMode(env);
224	  const runtime = createSpectrumFriendyRuntime({
225	    interpreter: interpreter ?? createOpenAIInterpreter({ ...modelConfig, strictMode }),
226	    now,
227	    repo,
228	    tools,
229	    expression,
230	    onboarding,
231	    requeueDeferredContactsOnStart,
232	    env
233	  });
234	
235	  // Keep Spectrum as a communication surface; relationship-memory decisions stay in the core agent.
236	  const app = await Spectrum({
237	    projectId,
238	    projectSecret,
239	    providers: [imessage.config()]
240	  });
241	
242	  for await (const [space, message] of app.messages) {
243	    await space.responding(async () => {
244	      await respondToSpectrumInbound({
245	        runtime,
246	        input: {
247	          text: message.content.type === "text" ? message.content.text : "",
248	          spaceId: space.id,
249	          receivedAt: new Date().toISOString()
250	        },
251	        reply: async (text) => {
252	          await message.reply(text);
253	        }
254	      });
255	    });
256	  }
257	}
258	
259	function createEnvExpressionComposer(env: Partial<NodeJS.ProcessEnv>): AgentExpressionComposer {
260	  return {
261	    polishOutboundText(input) {
262	      return polishOutboundText({
263	        ...input,
264	        config: readExpressionConfig(env)
265	      });
266	    }
267	  };
268	}
269	
270	function toAgentTurnLog(inbound: InboundAgentMessage, agentReply: string, createdAt: string): AgentTurnLog {
271	  return {
272	    userId: inbound.userId,
273	    platform: inbound.platform,
274	    spaceId: inbound.spaceId,
275	    userText: inbound.text,
276	    agentReply,
277	    createdAt
278	  };
279	}
280	
281	function resolveSpectrumUserId(input: SpectrumInboundInput, env: Partial<NodeJS.ProcessEnv>): string {
282	  // Prefer explicit transport user id, then env owner id, then Spectrum space id, then fixture fallback.
283	  return input.userId?.trim() || resolveConfiguredUserId(env) || input.spaceId?.trim() || fixtureUser.id;
284	}
285	
286	function toCompactInteractionLog(interaction: AgentInteraction): CompactInteractionLog {
287	  const intent =
288	    typeof interaction.interpretedIntentJson === "object" &&
289	    interaction.interpretedIntentJson !== null &&
290	    "intent" in interaction.interpretedIntentJson
291	      ? String(interaction.interpretedIntentJson.intent)
292	      : "unknown";
293	
294	  return {
295	    interactionId: interaction.id,
296	    userId: interaction.userId,
297	    platform: interaction.platform,
298	    intent,
299	    toolCalls: interaction.toolCalls,
300	    trace: toCompactTrace(interaction.redactedTraceJson),
301	    modelUsed: interaction.modelUsed,
302	    confidence: interaction.confidence,
303	    latencyMs: interaction.latencyMs,
304	    error: interaction.error ? "present" : undefined,
305	    createdAt: interaction.createdAt
306	  };
307	}
308	
309	function toCompactTrace(trace: unknown): CompactInteractionLog["trace"] | undefined {
310	  // Redacted traces are persisted as loose JSON; accept partial shapes without failing the transport log.
311	  if (typeof trace !== "object" || trace === null || !("traceId" in trace)) {
312	    return undefined;
313	  }
314	
315	  const value = trace as {
316	    traceId?: unknown;
317	    strictMode?: unknown;
318	    routeSource?: unknown;
319	    fallbackUsed?: unknown;
320	    scopeDecision?: unknown;
321	    activeWorkflowKind?: unknown;
322	    selectedTool?: unknown;
323	    modelRequested?: unknown;
324	    modelResponseSchemaValid?: unknown;
325	    modelErrorCode?: unknown;
326	    toolCalls?: unknown;
327	    candidateIdsTouched?: unknown;
328	    memoryIdsTouched?: unknown;
329	    errors?: unknown;
330	    search?: unknown;
331	  };
332	  if (typeof value.traceId !== "string") {
333	    return undefined;
334	  }
335	
336	  const search = typeof value.search === "object" && value.search !== null ? value.search as { outcome?: unknown } : undefined;
337	  return {
338	    traceId: value.traceId,
339	    toolCallCount: Array.isArray(value.toolCalls) ? value.toolCalls.length : 0,
340	    candidateCount: Array.isArray(value.candidateIdsTouched) ? value.candidateIdsTouched.length : 0,
341	    memoryCount: Array.isArray(value.memoryIdsTouched) ? value.memoryIdsTouched.length : 0,
342	    hasError: Array.isArray(value.errors) && value.errors.length > 0,
343	    strictMode: typeof value.strictMode === "boolean" ? value.strictMode : undefined,
344	    routeSource: typeof value.routeSource === "string" ? value.routeSource : undefined,
345	    fallbackUsed: typeof value.fallbackUsed === "boolean" ? value.fallbackUsed : undefined,
346	    scopeDecision: typeof value.scopeDecision === "string" ? value.scopeDecision : undefined,
347	    activeWorkflowKind: typeof value.activeWorkflowKind === "string" ? value.activeWorkflowKind : undefined,
348	    selectedTool: typeof value.selectedTool === "string" ? value.selectedTool : undefined,
349	    modelRequested: typeof value.modelRequested === "string" ? value.modelRequested : undefined,
350	    modelResponseSchemaValid:
351	      typeof value.modelResponseSchemaValid === "boolean" ? value.modelResponseSchemaValid : undefined,
352	    modelErrorCode: typeof value.modelErrorCode === "string" ? value.modelErrorCode : undefined,
353	    searchOutcome: typeof search?.outcome === "string" ? search.outcome : undefined
354	  };
355	}
356	
357	if (import.meta.url === `file://${process.argv[1]}`) {
358	  startSpectrumFriendyAgent().catch((error) => {
359	    console.error(error);
360	    process.exit(1);
361	  });
362	}
